import js from '@eslint/js'
import globals from 'globals'
import jsxA11y from 'eslint-plugin-jsx-a11y'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import storybook from 'eslint-plugin-storybook'
import tseslint from 'typescript-eslint'
import { globalIgnores } from 'eslint/config'

export default tseslint.config(
  // src/styles/tokens and platforms/ are both auto-generated by style-dictionary.config.mjs
  // (`npm run tokens:build`) — never hand-edited, so never linted. `.claude/` holds agent
  // worktrees (full copies of this repo); flat config doesn't read .gitignore, so without this
  // every warning is counted once per worktree.
  globalIgnores(['dist', 'storybook-static', 'coverage', 'src/styles/tokens', 'platforms', '**/.claude/**']),
  {
    // The Node tooling: scripts/, the Style Dictionary pipeline, and the other root configs.
    // These run in CI and in target repos (apply-process), so they get the same recommended
    // rules as the app code, with Node globals instead of browser ones. Scoped to those
    // locations: a browser-side .js file elsewhere (a service worker in public/) shouldn't be
    // linted as Node.
    files: ['scripts/**/*.{js,mjs,cjs}', '*.{js,mjs,cjs}'],
    extends: [js.configs.recommended],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: globals.node,
    },
  },
  {
    files: ['scripts/**/*.cjs', '*.cjs'],
    languageOptions: { sourceType: 'commonjs' },
  },
  {
    files: ['**/*.{ts,tsx}'],
    // jsx-a11y catches accessibility mistakes at lint time (missing labels, bad roles, click
    // handlers without keyboard equivalents). Accessibility is a bar here, not a nicety, so
    // it's enforced on the same footing as the type and hooks rules.
    extends: [js.configs.recommended, ...tseslint.configs.recommended, jsxA11y.flatConfigs.recommended],
    plugins: {
      'react-hooks': reactHooks,
      'react-refresh': reactRefresh,
    },
    rules: {
      ...reactHooks.configs['recommended-latest'].rules,
      ...reactRefresh.configs.vite.rules,
    },
    languageOptions: {
      ecmaVersion: 2022,
      globals: globals.browser,
    },
  },
  {
    // UI primitives idiomatically co-export a cva() variants function alongside the
    // component (`export { Button, buttonVariants }`) so callers can reuse the same
    // variant classes elsewhere — that's not compatible with react-refresh's
    // components-only-export constraint, and it's fine: these are library files, not
    // routed pages, so fast-refresh granularity doesn't matter here.
    files: ['src/components/ui/**/*.tsx'],
    rules: {
      'react-refresh/only-export-components': 'off',
    },
  },
  ...storybook.configs['flat/recommended'],
)
